{
  "title": "The Clockwork Rescue",
  "gate_token": "whCa3OxxO5OnO1nui_gAOA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined royal city.",
      "visual_description": "A vast ruined city with broken spires and tattered royal banners flapping in the wind, seen from a hilltop at dusk.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The city gates are twisted but unguarded.",
      "visual_description": "Massive iron gates, warped and ajar, covered in rust and old vines. A single lamp flickers above the archway.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "They pass through a cursed tower's shadow.",
      "visual_description": "A leaning tower with black stone and glowing runes, casting a long shadow across a cobblestone plaza.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Rumors of a dragon reach their ears from a frightened townsman.",
      "visual_description": "A huddled figure in a doorway whispers urgently, pointing toward a distant smoke plume. The team listens.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Old royal banners hang from broken poles.",
      "visual_description": "A wide avenue lined with shattered statues and banners bearing faded crests, flapping in the eerie silence.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march in the distance.",
      "visual_description": "A squad of faceless metal-clad figures moves in lockstep between crumbling columns, their footsteps echoing.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The sleeping tax collector awakens briefly.",
      "visual_description": "The tax collector stirs on a stone bench, papers falling; he mutters about tolls before dozing again.",
      "characters": ["sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door bars their path.",
      "visual_description": "A shimmering door of light set into a blank wall, pulsing with a soft hum. A keyhole glows at its center.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp reveals the door's riddle.",
      "visual_description": "The lamp's flame eye narrows as it speaks, casting shadows that form the shape of a key on the ground.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver swims through a window to bypass the door.",
      "visual_description": "The diver presses against a cracked window, then steps through it like water, emerging on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside a treasury room, they find the tax collector's stamp.",
      "visual_description": "A dusty chamber with coin piles and ledgers; the sleeping tax collector's stamp lies on a pedestal.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox scouts ahead through a collapsed hall.",
      "visual_description": "The little metal fox picks its way over rubble, blue eyes scanning for threats in the dim light.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara reads her map at a crossroads.",
      "visual_description": "Mara holds a brass compass and unrolls a worn map, her ink-stained fingers tracing a path. The others wait behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Patrols close in from two directions.",
      "visual_description": "Armored figures appear at both ends of a narrow street, their weapons glinting. The team presses into a doorway.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The tax collector accidentally triggers a secret passage.",
      "visual_description": "While leaning against a wall, the sleeping tax collector's elbow hits a loose stone, revealing a hidden stair.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge onto a high bridge over a chasm.",
      "visual_description": "A stone bridge spans a deep gorge, with broken railings and a roaring wind. The exit gate is visible at the far end.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Patrols chase onto the bridge as the team rushes.",
      "visual_description": "Armored figures clank onto the bridge behind them; the glass diver turns to slow them with a shimmering mirror.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge and escape the ruined city.",
      "visual_description": "The team reaches the far side, the city gates collapsing behind them. Dawn light breaks over the horizon.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

